package main

// 原程序内嵌的 BCRYPT_RSAFULLPRIVATE_BLOB（RVA 0x1400FB140，2048 位）。
// 仅用于本地解密已缓存的响应信封，便于核对缓存内容。

import (
	"crypto/rsa"
	"math/big"
)

const (
	rsaN = ""
	rsaE = 65537
	rsaD = ""
	rsaP = "c528f750b98bab7eba1d96305d6a4f72530a12937a2491b47b818bc70cf7526a77e718a9003a9871a3df7c372d9c043c3e96c7c006d05cbe288629494c6430c962df7ec0631dbeb5ee214eb01438ac64cc04410892b531cd531fc2e597a1352475b33cd485a73b9351d4ffc89f70e9b325fd688072d1d1cb5b4297f3520327cf"
	rsaQ = "bdc835ef25052da4e462ce63eeec439bd4a93ce56964378f81d13cd5415170f12fda819170170d089687b62d82d402bdc6b973aa37179fa8c2756603b67f945f849e2f9352ca1b9b765d597c650356b1b6c8e55762b50e1fdcca7dfe1153e5ce68a0b045bd8eb4ccced753e4ce1f1e69c9c0fa3f20b14bdde4c861f741db9dff"
)

func loadPrivateKey() *rsa.PrivateKey {
	toInt := func(s string) *big.Int {
		v, ok := new(big.Int).SetString(s, 16)
		if !ok {
			return big.NewInt(0)
		}
		return v
	}
	priv := &rsa.PrivateKey{
		PublicKey: rsa.PublicKey{N: toInt(rsaN), E: rsaE},
		D:         toInt(rsaD),
		Primes:    []*big.Int{toInt(rsaP), toInt(rsaQ)},
	}
	_ = priv.Validate()
	priv.Precompute()
	return priv
}
